import type { ArcadeItem } from './schemas';

const PUBLISHED_ON = '2026-11-16';

type Phase4cEditorialSpec = {
  id: string;
  slug: string;
  title: string;
  moduleId: ArcadeItem['moduleId'];
  component: string;
  category: string;
  tags: string[];
  summary: string;
  seoDescription: string;
  instructions: string;
  controls: string[];
  relatedSlugs: string[];
  setup: string;
  loop: string;
  mechanic: string;
  feedback: string;
  objective: string;
  replay: string;
  pointer: string;
  keyboard: string;
  restart: string;
  pause: string;
  rules: string;
  scoring: string;
  finish: string;
  tipOne: string;
  tipTwo: string;
  tipThree: string;
  relatedIntro: string;
};

function makeDocumentation(spec: Phase4cEditorialSpec): ArcadeItem['documentation'] {
  return {
    howToPlay: [
      `${spec.setup} ${spec.loop} This opening sequence establishes the current board and makes clear whose move or puzzle action comes next, so there is no hidden setup to infer.`,
      `${spec.mechanic} ${spec.feedback} Treat the visible board as the source of truth: a rejected move leaves the game state unchanged, while an accepted action updates the counters and the accessible status message.`,
      `${spec.objective} ${spec.replay} A completed result stays visible until you choose to reset, which gives you time to read the outcome before deciding whether to try another arrangement.`,
    ],
    controls: [
      `${spec.pointer} Each action is a labeled native button or standard form control; on a touch screen, tap once to choose and once more only when the game explicitly asks for a destination or confirmation.`,
      `${spec.keyboard} Tab follows the visible control order, and Enter or Space activates a focused button. The status message describes accepted moves and rejected choices in words, so the board does not depend on color, sound, or animation alone.`,
      `${spec.restart} The Reset to seeded start control restores the same starting state instead of continuing a previous run. If the page becomes hidden or loses browser focus, input and any running clock pause; returning restores the same board and remaining time.`,
    ],
    rulesAndScoring: [
      `${spec.rules} The module validates the selected action before committing it, and an illegal or unavailable choice does not change a score, move total, turn, or puzzle clue. There is no remote opponent, purchase, or network-dependent game state.`,
      `${spec.scoring} The scoreboard shows the measures that matter for this title, such as moves, found items, remaining seconds, captured pieces, or claimed squares. It does not award points for speed unless the displayed rule explicitly says that time is a limit.`,
      `${spec.finish} This is the only normal game-over boundary for the current session; ordinary selections, mode changes, successful intermediate moves, and player changes are not completion events. A reset starts a reproducible new attempt and clears the previous result.`,
    ],
    tips: [spec.tipOne, spec.tipTwo, spec.tipThree],
    relatedIntro: spec.relatedIntro,
  };
}

